    const cameraPositionXS = useSpring(cameraPositionXMV, springOptions)
    useEffect(() => {
        cameraPositionXMV.set(cameraPosition.x)
    }, [cameraPosition.x])

    const cameraPositionYMV = useMotionValue(cameraPosition.y)
    const cameraPositionYS = useSpring(cameraPositionYMV, springOptions)
    useEffect(() => {
        cameraPositionYMV.set(cameraPosition.y)
    }, [cameraPosition.y])

    const cameraPositionZMV = useMotionValue(cameraPosition.z)
